(function(root){
const today=()=>new Date().toISOString().slice(0,10);
function seed(){return {products:[{id:'SP001',name:'Gạo ST25 túi 5kg',category:'Thực phẩm',unit:'Túi',price:165000,min:30,active:true},{id:'SP002',name:'Nước suối Lavie 500ml',category:'Đồ uống',unit:'Thùng',price:95000,min:20,active:true},{id:'SP003',name:'Sữa tươi Vinamilk 1L',category:'Đồ uống',unit:'Hộp',price:34000,min:25,active:true},{id:'SP004',name:'Dầu ăn Tường An 1L',category:'Thực phẩm',unit:'Chai',price:52000,min:20,active:true},{id:'SP005',name:'Giấy vệ sinh 10 cuộn',category:'Gia dụng',unit:'Lốc',price:68000,min:15,active:true},{id:'SP006',name:'Bột giặt OMO 3kg',category:'Gia dụng',unit:'Túi',price:142000,min:20,active:true}],locations:[{id:'K01',name:'Kho trung tâm',type:'Kho',capacity:1500},{id:'B01',name:'Bãi lưu trữ phía Đông',type:'Bãi',capacity:800},{id:'CH01',name:'Cửa hàng Quận 1',type:'Cửa hàng',capacity:400}],stock:[{product:'SP001',location:'K01',qty:280},{product:'SP002',location:'K01',qty:185},{product:'SP003',location:'K01',qty:12},{product:'SP004',location:'K01',qty:95},{product:'SP005',location:'B01',qty:120},{product:'SP006',location:'CH01',qty:18}],partners:[{id:'NCC01',name:'Công ty thực phẩm An Phát',type:'Nhà cung cấp',phone:'0901234567'},{id:'NCC02',name:'Phân phối Minh Long',type:'Nhà cung cấp',phone:'0912345678'},{id:'KH01',name:'Cửa hàng Bách Hóa Xanh demo',type:'Khách hàng',phone:'0987654321'}],docs:[],logs:[]};}
function stock(s,p,l){return s.stock.find(x=>x.product===p&&x.location===l)?.qty||0;}
function apply(s,d){if(d.status!=='Đã duyệt')throw Error('Phiếu phải được duyệt trước khi hoàn thành.');let p=s.products.find(p=>p.id===d.product);if(!p)throw Error('Sản phẩm không tồn tại.');let q=Number(d.qty);if(!Number.isInteger(q)||q<0||(d.type!=='Kiểm kê'&&q===0))throw Error('Số lượng không hợp lệ.');let from=s.locations.find(l=>l.id===d.from),to=s.locations.find(l=>l.id===d.to);if(!from)throw Error('Nơi lưu trữ không tồn tại.');if(d.type==='Điều chuyển'&&(!to||to.id===from.id))throw Error('Nơi đến phải khác nơi đi.');const outgoing=['Xuất hàng','Điều chuyển','Bán hàng','Trả NCC'].includes(d.type);if(outgoing&&stock(s,p.id,from.id)<q)throw Error('Không đủ tồn kho khả dụng.');let target=d.type==='Điều chuyển'?to:from;let add=d.type==='Nhập hàng'||d.type==='Điều chuyển'?q:d.type==='Kiểm kê'?q-stock(s,p.id,from.id):0;if(add>0&&s.stock.filter(x=>x.location===target.id).reduce((a,x)=>a+x.qty,0)+add>target.capacity)throw Error('Vượt sức chứa của nơi lưu trữ.');function change(l,n){let row=s.stock.find(x=>x.product===p.id&&x.location===l);if(!row){row={product:p.id,location:l,qty:0};s.stock.push(row);}row.qty+=n;}
if(outgoing)change(from.id,-q);if(d.type==='Nhập hàng')change(from.id,q);if(d.type==='Điều chuyển')change(to.id,q);if(d.type==='Kiểm kê'){d.before=stock(s,p.id,from.id);change(from.id,q-d.before);}d.status='Hoàn thành';d.completed=today();return d;}
const api={seed,stock,apply,today};if(typeof module!=='undefined')module.exports=api;else root.Core=api;
})(typeof window!=='undefined'?window:globalThis);
